def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Find positions where strings differ
    diff_positions = []
    for i, (c_in, c_out) in enumerate(zip(s_in, s_out)):
        if c_in != c_out:
            diff_positions.append(i)

    # If lengths differ, check if it's a simple insertion/deletion
    if len(s_in) != len(s_out):
        # Check if we're removing a character from s_in
        if len(s_in) > len(s_out):
            # s_in is longer, so we removed a char
            for i in range(len(s_out)):
                if s_in[i] != s_out[i]:
                    return s_in[i], "", i
            # If we got here, the difference is at the end
            return s_in[-1], "", len(s_out)
        else:
            # s_out is longer, so we added a char  
            for i in range(len(s_in)):
                if s_in[i] != s_out[i]:
                    return "", s_out[i], i
            # If we got here, the difference is at the end
            return "", s_out[-1], len(s_in)

    # Same length - find first differing position
    for i in range(len(s_in)):
        if s_in[i] != s_out[i]:
            return s_in[i], s_out[i], i

    return "", "", -1

inputs = ['ziuy', 'kaj', 'uhyg', 'cz', 'ywuzxd']
outputs = ['hiuy', 'kaj', 'uhyg', 'ch', 'ywuhxd']

changed_pairs = [(0, 'ziuy', 'hiuy'), (3, 'cz', 'ch'), (4, 'ywuzxd', 'ywuhxd')]

for idx, inp, outp in changed_pairs:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}'")
    print(f"  Edit: '{old_sub}' -> '{new_sub}' at position {pos}")

